app.get('/download-app',async(req,res)=>{try{if(useDb){const q=await pool.query('SELECT version,apk_data,apk_mime,file_name FROM app_releases WHERE published=true ORDER BY created_at DESC,id DESC LIMIT 1');if(q.rowCount){const x=q.rows[0];res.setHeader('Content-Type',x.apk_mime||'application/vnd.android.package-archive');res.setHeader('Content-Disposition','attachment; filename="'+String(x.file_name||'CIE_Online_Exam.apk').replace(/[\"\r\n]/g,'')+'"');return res.send(x.apk_data)}}const f=path.join(__dirname,'public','downloads','CIE_Online_Exam.apk');if(fs.existsSync(f))return res.download(f,'CIE_Online_Exam.apk');res.status(404).send('<h2>CIE Exam App APK is being updated.</h2><p>Please check again shortly.</p>')}catch(e){res.status(500).send('APK download temporarily unavailable.')}});
app.use(express.static(path.join(__dirname,'public'),{index:false}));

app.get('/api/public/app-info',async(req,res)=>{try{if(!useDb)return res.json({available:false});const q=await pool.query('SELECT version,notes,created_at AS "publishedAt" FROM app_releases WHERE published=true ORDER BY created_at DESC,id DESC LIMIT 1');res.json(q.rowCount?{available:true,...q.rows[0],downloadUrl:'/download-app'}:{available:false})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/exams/:id/thumbnail',async(req,res)=>{try{if(!useDb||!/^\d+$/.test(req.params.id))return res.status(404).end();const q=await pool.query('SELECT thumbnail_data,thumbnail_mime FROM exams WHERE id=$1',[req.params.id]);if(!q.rowCount||!q.rows[0].thumbnail_data)return res.status(404).end();res.setHeader('Content-Type',q.rows[0].thumbnail_mime||'image/jpeg');res.setHeader('Cache-Control','public,max-age=300');res.send(q.rows[0].thumbnail_data)}catch(e){res.status(500).end()}});
app.get('/api/public/exams',async(req,res)=>{try{if(!useDb)return res.json([]);const q=await pool.query(`SELECT id,name,start_at AS "startAt",end_at AS "endAt",timer_mode AS "timerMode",duration_minutes AS "durationMinutes",per_question_seconds AS "perQuestionSeconds",question_limit AS "questionLimit",passing_percentage AS "passingPercentage",attempt_limit AS "attemptLimit",random_questions AS "randomQuestions",active,thumbnail_mime FROM exams WHERE active=true ORDER BY CASE WHEN start_at IS NULL THEN 1 ELSE 0 END,start_at ASC,id DESC LIMIT 12`);res.json(q.rows.map(x=>({...x,thumbnailUrl:x.thumbnail_mime?('/api/exams/'+Number(x.id)+'/thumbnail'):null,status:nowStatus(examPublic(x))})))}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/public/promotions',async(req,res)=>{try{if(!useDb)return res.json([]);const q=await pool.query('SELECT id,title,subtitle,details,link_text AS "linkText",link_url AS "linkUrl" FROM promotions WHERE active=true ORDER BY sort_order,id');res.json(q.rows)}catch(e){res.status(500).json({error:e.message})}});

app.post('/api/admin/auth/login',async(req,res)=>{try{if(!useDb)return res.status(503).json({error:'Database required.'});const adminId=norm(req.body?.adminId),password=String(req.body?.password||'');if(!adminId||!password)return res.status(400).json({error:'Enter Admin ID and Password.'});const q=await pool.query('SELECT admin_id,password_hash,active FROM admins WHERE admin_id=$1',[adminId]);if(!q.rowCount||!q.rows[0].active||!(await bcrypt.compare(password,q.rows[0].password_hash)))return res.status(401).json({error:'Admin ID or Password is incorrect.'});setAdminCookie(res,q.rows[0].admin_id);res.json({ok:true})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/auth/logout',(req,res)=>{clearAdminCookie(res);res.json({ok:true})});
app.get('/api/admin/auth/me',requireAdmin,async(req,res)=>{try{const q=await pool.query('SELECT admin_id AS "adminId",name,email FROM admins WHERE admin_id=$1',[req.admin.adminId]);res.json(q.rows[0]||{})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/auth/forgot',async(req,res)=>{try{if(!useDb)return res.status(503).json({error:'Database required.'});const adminId=norm(req.body?.adminId),email=norm(req.body?.email).toLowerCase();if(!adminId||!email)return res.status(400).json({error:'Enter Admin ID and registered Email.'});const q=await pool.query('SELECT admin_id,email FROM admins WHERE admin_id=$1 AND LOWER(email)=LOWER($2) AND active=true',[adminId,email]);if(!q.rowCount)return res.status(404).json({error:'Admin ID and Email do not match.'});const token=crypto.randomBytes(32).toString('hex'),hash=crypto.createHash('sha256').update(token).digest('hex');await pool.query('DELETE FROM admin_password_resets WHERE admin_id=$1 OR expires_at<NOW()',[adminId]);await pool.query("INSERT INTO admin_password_resets(admin_id,token_hash,expires_at) VALUES($1,$2,NOW()+INTERVAL '20 minutes')",[adminId,hash]);const resetUrl=`${req.protocol}://${req.get('host')}/admin/reset?token=${encodeURIComponent(token)}`;await sendAdminResetEmail(email,resetUrl);res.json({ok:true,message:'Password reset link sent to registered email.'})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/admin/auth/reset',async(req,res)=>{try{const token=String(req.body?.token||''),newPassword=String(req.body?.newPassword||'');if(token.length<20||newPassword.length<8)return res.status(400).json({error:'Invalid reset link or password must be at least 8 characters.'});const hash=crypto.createHash('sha256').update(token).digest('hex');const q=await pool.query('SELECT id,admin_id FROM admin_password_resets WHERE token_hash=$1 AND used_at IS NULL AND expires_at>NOW()',[hash]);if(!q.rowCount)return res.status(400).json({error:'Reset link is invalid or expired.'});const ph=await bcrypt.hash(newPassword,12);const c=await pool.connect();try{await c.query('BEGIN');await c.query('UPDATE admins SET password_hash=$1,updated_at=NOW() WHERE admin_id=$2',[ph,q.rows[0].admin_id]);await c.query('UPDATE admin_password_resets SET used_at=NOW() WHERE id=$1',[q.rows[0].id]);await c.query('COMMIT')}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}res.json({ok:true,message:'Password updated. You can login now.'})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/auth/change-password',requireAdmin,async(req,res)=>{try{const oldPassword=String(req.body?.oldPassword||''),newPassword=String(req.body?.newPassword||'');if(newPassword.length<8)return res.status(400).json({error:'New password must be at least 8 characters.'});const q=await pool.query('SELECT password_hash FROM admins WHERE admin_id=$1',[req.admin.adminId]);if(!q.rowCount||!(await bcrypt.compare(oldPassword,q.rows[0].password_hash)))return res.status(401).json({error:'Current password is incorrect.'});const ph=await bcrypt.hash(newPassword,12);await pool.query('UPDATE admins SET password_hash=$1,updated_at=NOW() WHERE admin_id=$2',[ph,req.admin.adminId]);res.json({ok:true,message:'Password changed successfully.'})}catch(e){res.status(500).json({error:e.message})}});

